export function attachUserNames(orders = [], users = []) {
  return orders.map(order => {
    const found = users.find(u => u.id === order.userId);
    return {
      orderId: order.orderId,
      userId: order.userId,
      userName: found ? found.name : 'UNKNOWN',
      amount: order.amount,
    };
  });
}

import {performance} from 'node:perf_hooks';
import {attachUserNames} from './src/join-orders.mjs';

const users = Array.from({length: 10000}, (_, i) => ({id: `u-${i}`, name: `User ${i}`}));
const orders = Array.from({length: 15000}, (_, i) => ({orderId: i + 1, userId: `u-${(i * 7) % 10000}`, amount: i * 10}));

for (let run = 1; run <= 3; run++) {
  const t0 = performance.now();
  const out = attachUserNames(orders, users);
  const elapsed = (performance.now() - t0).toFixed(2);
  console.log(`run ${run}: ${elapsed} ms (rows=${out.length})`);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {attachUserNames} from '../src/join-orders.mjs';

test('attaches matching userName and defaults to UNKNOWN', () => {
  const users = [{id: 'u1', name: 'Alice'}];
  const orders = [{orderId: 1, userId: 'u1', amount: 50}, {orderId: 2, userId: 'u9', amount: 20}];
  assert.deepEqual(attachUserNames(orders, users), [
    {orderId: 1, userId: 'u1', userName: 'Alice', amount: 50},
    {orderId: 2, userId: 'u9', userName: 'UNKNOWN', amount: 20}
  ]);
});

export function dedupLogLines(lines = []) {
  const seen = [];
  const result = [];
  for (const raw of lines) {
    const key = String(raw).trim();
    if (!key) continue;
    if (!seen.includes(key)) {
      seen.push(key);
      result.push(key);
    }
  }
  return result;
}

import {performance} from 'node:perf_hooks';
import {dedupLogLines} from './src/dedup-logs.mjs';

const lines = Array.from({length: 20000}, (_, i) => `  [INFO] event-id-${i % 12000}  `);
for (let run = 1; run <= 3; run++) {
  const t0 = performance.now();
  const out = dedupLogLines(lines);
  const elapsed = (performance.now() - t0).toFixed(2);
  console.log(`run ${run}: ${elapsed} ms (unique=${out.length})`);
}

import test from 'node:test';
import assert from 'node:assert/strict';
import {dedupLogLines} from '../src/dedup-logs.mjs';

test('dedupLogLines trims, skips empty and keeps first occurrence order', () => {
  assert.deepEqual(dedupLogLines([' a ', '', 'b', 'a', '  ', 'b', 'c']), ['a', 'b', 'c']);
});
